package com.example.mediqueue.model;
import jakarta.persistence.*;
@Entity @Table(name="room_beds",uniqueConstraints=@UniqueConstraint(columnNames={"room_number","bed_number"})) public class RoomBed{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=30)String roomNumber;@Column(nullable=false,length=30)String bedNumber;@Column(length=50)String ward;boolean occupied=false;@ManyToOne @JoinColumn(name="patient_id")Patient patient;public RoomBed(){}public Long getId(){return id;}public String getRoomNumber(){return roomNumber;}public void setRoomNumber(String v){roomNumber=v;}public String getBedNumber(){return bedNumber;}public void setBedNumber(String v){bedNumber=v;}public String getWard(){return ward;}public void setWard(String v){ward=v;}public boolean isOccupied(){return occupied;}public void setOccupied(boolean v){occupied=v;}public Patient getPatient(){return patient;}public void setPatient(Patient v){patient=v;}}
